"""Execution equivalence: gfortran-compiled reference vs Julia generated by fortran_to_julia.py.
Compares parsed float values within 1e-6 (not stdout strings)."""
import pathlib, shutil, subprocess, sys
import pytest

HERE = pathlib.Path(__file__).parent
sys.path.insert(0, str(HERE.parent))
from fortran_to_julia import transpile

SRC = HERE / "scalar_test.f90"
FIXTURE = HERE / "fixtures" / "scalar_test.jl"
MISSING = "gfortran/julia not in PATH — requires CI environment"


def test_fixture_is_generated_by_translator():
    assert transpile(SRC.read_text()) == FIXTURE.read_text()


@pytest.mark.skipif(not (shutil.which("gfortran") and shutil.which("julia")), reason=MISSING)
def test_scalar_equivalence(tmp_path):
    exe = tmp_path / "scalar_test"
    comp = subprocess.run(["gfortran", str(SRC), "-o", str(exe)], capture_output=True, text=True)
    assert comp.returncode == 0, f"gfortran failed: {comp.stderr}"
    f = subprocess.run([str(exe)], capture_output=True, text=True)
    assert f.returncode == 0, f"Fortran run failed: {f.stderr}"
    jl = tmp_path / "scalar_test.jl"
    jl.write_text(transpile(SRC.read_text()))  # freshly generated, not hand-written
    j = subprocess.run(["julia", "--startup-file=no", str(jl)], capture_output=True, text=True)
    assert j.returncode == 0, f"julia failed: {j.stderr}"
    fv, jv = float(f.stdout.split()[-1]), float(j.stdout.split()[-1])
    assert abs(fv - jv) < 1e-6, f"fortran={fv} julia={jv}"
